export function registerSpaRoutes(router, options) {
    const basePath = normalizeBasePath(options.basePath);
    const handler = options.handler;
    if (handler) {
        router.all(basePath || '/', (context) => serveSpaHandler(context.req.raw, options));
        router.all(`${basePath}/*`, (context) => serveSpaHandler(context.req.raw, options));
        return;
    }
    const rootDir = path.dirname(options.indexPath);
    const assetsRoutePath = joinBasePath(basePath, options.assetsPath ?? '/assets');
    router.all(assetsRoutePath, (context) => serveSpaAsset(context.req.raw, {
        rootDir,
        basePath,
    }));
    router.all(`${assetsRoutePath}/*`, (context) => serveSpaAsset(context.req.raw, {
        rootDir,
        basePath,
    }));
    router.get(basePath || '/', () => serveSpaIndex(options.indexPath, {
        clientConfig: options.clientConfig,
        publicConfig: resolvePublicConfig(options),
        publicBasePath: options.publicBasePath,
    }));
    router.get(`${basePath}/*`, () => serveSpaIndex(options.indexPath, {
        clientConfig: options.clientConfig,
        publicConfig: resolvePublicConfig(options),
        publicBasePath: options.publicBasePath,
    }));

